calls = []

def logged(f):
    def wrapper(*args, **kwargs):
        calls.append(f.__name__)
        return f(*args, **kwargs)
    return wrapper

@logged
def a():
    pass

@logged
def b():
    pass

a()
b()
a()
print(calls)

